

clc;
clear;
close all;

%%\ AUTOMOTIVE ENGINE FAULT DETECTION
% FFT, Spectral Analysis and Acoustic Feature Extraction
%
% Required files:
% normal_engine.wav
% test_engine.wav
%
% Additional features:
% 1. Sound Pressure Level / Relative Acoustic Level
% 2. Harmonic Content
% 3. Engine Order Analysis
% 4. Background Noise
% 5. Acoustic Anomaly Detection
% 6. RPM-Related Sound Analysis
% 7. Crest Factor

normalFile = 'normal_engine.wav';
testFile   = 'test_engine.wav';

%%\ USER SETTINGS

% Change this value to the known engine RPM.
% Used for engine order analysis.
engineRPM = 1500;

% Assumed engine order for estimating RPM from dominant frequency.
% Change according to the engine and its acoustic characteristics.
selectedOrder = 2;

% Calibration offset in dB.
% Leave at 0 if no microphone calibration is available.
% True SPL requires a calibrated microphone or reference measurement.
calibrationOffset_dB = 0;

% Maximum harmonic number to analyze
maxHarmonics = 10;

% Frequency range used for acoustic analysis
minAnalysisFreq = 20;

%%\ 1. CHECK AUDIO FILES

if ~isfile(normalFile)
    error('File not found: %s', normalFile);
end

if ~isfile(testFile)
    error('File not found: %s', testFile);
end

%%\ 2. LOAD AUDIO SIGNALS

[normalSig, Fs1] = audioread(normalFile);
[testSig, Fs2] = audioread(testFile);

% Convert stereo audio to mono
if size(normalSig, 2) > 1
    normalSig = mean(normalSig, 2);
end

if size(testSig, 2) > 1
    testSig = mean(testSig, 2);
end

% Match sampling rates
if Fs1 ~= Fs2
    testSig = resample(testSig, Fs1, Fs2);
end

Fs = Fs1;

% Remove DC component.
% IMPORTANT: Do not peak-normalize the signals because that
% would distort RMS, acoustic-level and crest-factor comparisons.

normalSig = normalSig - mean(normalSig);
testSig   = testSig - mean(testSig);

%%\ 3. TIME-DOMAIN ANALYSIS

t1 = (0:numel(normalSig)-1)' / Fs;
t2 = (0:numel(testSig)-1)' / Fs;

figure('Name','Time Domain Analysis'); %[output:708251ec]

subplot(2,1,1); %[output:708251ec]
plot(t1, normalSig); %[output:708251ec]
title('Normal Engine - Time Domain'); %[output:708251ec]
xlabel('Time (s)'); %[output:708251ec]
ylabel('Amplitude'); %[output:708251ec]
grid on; %[output:708251ec]

subplot(2,1,2); %[output:708251ec]
plot(t2, testSig); %[output:708251ec]
title('Test Engine - Time Domain'); %[output:708251ec]
xlabel('Time (s)'); %[output:708251ec]
ylabel('Amplitude'); %[output:708251ec]
grid on; %[output:708251ec]

%%\ 4. FFT ANALYSIS

N1 = numel(normalSig);
N2 = numel(testSig);

nfft1 = 2^nextpow2(N1);
nfft2 = 2^nextpow2(N2);

w1 = hann(N1,'periodic');
w2 = hann(N2,'periodic');

Y1 = fft(normalSig .* w1,nfft1);
Y2 = fft(testSig .* w2,nfft2);

P1 = abs(Y1) / sum(w1);
P2 = abs(Y2) / sum(w2);

P1 = P1(1:floor(nfft1/2)+1);
P2 = P2(1:floor(nfft2/2)+1);

if numel(P1) > 2
    P1(2:end-1) = 2 * P1(2:end-1);
end

if numel(P2) > 2
    P2(2:end-1) = 2 * P2(2:end-1);
end

f1 = (0:floor(nfft1/2))' * Fs/nfft1;
f2 = (0:floor(nfft2/2))' * Fs/nfft2;

%%\ 5. FREQUENCY-DOMAIN PLOTS

figure('Name','FFT Spectrum'); %[output:87d319ae]

subplot(2,1,1); %[output:87d319ae]
plot(f1,P1); %[output:87d319ae]
title('Normal Engine - FFT Spectrum'); %[output:87d319ae]
xlabel('Frequency (Hz)'); %[output:87d319ae]
ylabel('Magnitude'); %[output:87d319ae]
xlim([0 Fs/2]); %[output:87d319ae]
grid on; %[output:87d319ae]

subplot(2,1,2); %[output:87d319ae]
plot(f2,P2); %[output:87d319ae]
title('Test Engine - FFT Spectrum'); %[output:87d319ae]
xlabel('Frequency (Hz)'); %[output:87d319ae]
ylabel('Magnitude'); %[output:87d319ae]
xlim([0 Fs/2]); %[output:87d319ae]
grid on; %[output:87d319ae]

%[text] 
%%\ 6. BASIC FEATURE EXTRACTION

% Ignore DC and frequencies below the analysis limit
valid1 = find(f1 >= minAnalysisFreq);
valid2 = find(f2 >= minAnalysisFreq);

if isempty(valid1) || isempty(valid2)
    error('Audio sampling rate is too low for the selected frequency range.');
end

[peak1, idx1] = max(P1(valid1));
dominantIdx1 = valid1(idx1);
dominantNormal = f1(dominantIdx1);

[peak2, idx2] = max(P2(valid2));
dominantIdx2 = valid2(idx2);
dominantTest = f2(dominantIdx2);

% RMS amplitude
rmsNormal = sqrt(mean(normalSig.^2));
rmsTest   = sqrt(mean(testSig.^2));

% Spectral centroid
centroidNormal = sum(f1 .* P1) / (sum(P1) + eps);
centroidTest   = sum(f2 .* P2) / (sum(P2) + eps);

% Spectral energy proxy
energyNormal = sum(P1.^2);
energyTest   = sum(P2.^2);

%%\ 7. SOUND PRESSURE LEVEL / ACOUSTIC LEVEL

% Without microphone calibration, these are dBFS values,
% not calibrated physical sound pressure levels in dB SPL.
%
% If a valid calibration offset is available, it can be added
% to the digital level to estimate calibrated SPL.

levelNormal_dB = 20*log10(rmsNormal + eps);
levelTest_dB   = 20*log10(rmsTest + eps);

SPLNormal_dB = levelNormal_dB + calibrationOffset_dB;
SPLTest_dB   = levelTest_dB + calibrationOffset_dB;

%%\ 8. HARMONIC CONTENT ANALYSIS

% Harmonics occur near integer multiples of a fundamental
% frequency. The strongest peak is only a proxy for the
% fundamental, so interpret this feature carefully.

harmonicEnergyNormal = zeros(maxHarmonics,1);
harmonicEnergyTest   = zeros(maxHarmonics,1);

df1 = Fs/nfft1;
df2 = Fs/nfft2;

for k = 1:maxHarmonics

    targetFreq1 = k * dominantNormal;
    targetFreq2 = k * dominantTest;

    % Skip harmonics above Nyquist frequency
    if targetFreq1 < Fs/2
        idx = find(abs(f1-targetFreq1) <= max(df1,2));
        harmonicEnergyNormal(k) = sum(P1(idx).^2);
    end

    if targetFreq2 < Fs/2
        idx = find(abs(f2-targetFreq2) <= max(df2,2));
        harmonicEnergyTest(k) = sum(P2(idx).^2);
    end
end

totalHarmonicNormal = sum(harmonicEnergyNormal);
totalHarmonicTest   = sum(harmonicEnergyTest);

% Harmonic energy as a percentage of total spectral energy
harmonicPercentNormal = 100 * totalHarmonicNormal / ...
    (sum(P1.^2) + eps);

harmonicPercentTest = 100 * totalHarmonicTest / ...
    (sum(P2.^2) + eps);

% Harmonic-to-nonharmonic energy ratio in dB
nonHarmonicNormal = max(energyNormal-totalHarmonicNormal,eps);
nonHarmonicTest   = max(energyTest-totalHarmonicTest,eps);

harmonicRatioNormal_dB = 10*log10( ...
    (totalHarmonicNormal+eps)/nonHarmonicNormal);

harmonicRatioTest_dB = 10*log10( ...
    (totalHarmonicTest+eps)/nonHarmonicTest);

%%\ 9. ENGINE ORDER ANALYSIS

% Engine order = acoustic frequency / shaft rotation frequency
% Shaft rotation frequency = RPM/60

if engineRPM <= 0
    error('Engine RPM must be greater than zero.');
end

shaftFreq = engineRPM/60;

engineOrderNormal = dominantNormal/shaftFreq;
engineOrderTest   = dominantTest/shaftFreq;

% Approximate frequencies for the first six engine orders
orderNumbers = (1:6)';

orderFreqNormal = orderNumbers * shaftFreq;
orderFreqTest   = orderNumbers * shaftFreq;

% Find spectral magnitude nearest each expected order frequency
orderMagNormal = interp1(f1,P1,orderFreqNormal,'linear',0);
orderMagTest   = interp1(f2,P2,orderFreqTest,'linear',0);

figure('Name','Engine Order Analysis'); %[output:06a31e1f]

subplot(2,1,1); %[output:06a31e1f]
stem(orderNumbers,orderMagNormal,'filled'); %[output:06a31e1f]
title('Normal Engine - Order Spectrum'); %[output:06a31e1f]
xlabel('Engine Order'); %[output:06a31e1f]
ylabel('Magnitude'); %[output:06a31e1f]
grid on; %[output:06a31e1f]

subplot(2,1,2); %[output:06a31e1f]
stem(orderNumbers,orderMagTest,'filled'); %[output:06a31e1f]
title('Test Engine - Order Spectrum'); %[output:06a31e1f]
xlabel('Engine Order'); %[output:06a31e1f]
ylabel('Magnitude'); %[output:06a31e1f]
grid on; %[output:06a31e1f]

%%\ 10. BACKGROUND NOISE ESTIMATION

% Estimate the spectral noise floor using the median magnitude
% in the analysis band. This is a relative noise-floor estimate,
% not a calibrated measurement of environmental noise.

noiseBand1 = P1(f1 >= minAnalysisFreq);
noiseBand2 = P2(f2 >= minAnalysisFreq);

noiseFloorNormal = median(noiseBand1);
noiseFloorTest   = median(noiseBand2);

noiseFloorNormal_dB = 20*log10(noiseFloorNormal+eps);
noiseFloorTest_dB   = 20*log10(noiseFloorTest+eps);

%%\ 11. ACOUSTIC ANOMALY DETECTION

% Identify local spectral peaks that are:
% 1. Above five times the estimated noise floor.
% 2. At least three times the normal spectrum magnitude
%    at the corresponding frequency.
%
% This is a simple screening method, not a trained classifier.

isLocalPeak = false(size(P2));

if numel(P2) >= 3
    isLocalPeak(2:end-1) = ...
        P2(2:end-1) > P2(1:end-2) & ...
        P2(2:end-1) >= P2(3:end);
end

normalAtTestFreq = interp1(f1,P1,f2,'linear',0);

anomalyMask = isLocalPeak & ...
    f2 >= minAnalysisFreq & ...
    P2 > 5*noiseFloorTest & ...
    P2 > 3*normalAtTestFreq;

anomalyFreq = f2(anomalyMask);
anomalyMag  = P2(anomalyMask);

% Sort anomalies by spectral magnitude, strongest first
[anomalyMag, sortIdx] = sort(anomalyMag,'descend');
anomalyFreq = anomalyFreq(sortIdx);

% Keep at most 10 strongest candidate anomalies
numAnomalies = min(10,numel(anomalyFreq));

anomalyFreq = anomalyFreq(1:numAnomalies);
anomalyMag  = anomalyMag(1:numAnomalies);

figure('Name','Acoustic Anomaly Analysis'); %[output:70fecfc1]

plot(f2,P2,'b'); %[output:70fecfc1]
hold on; %[output:70fecfc1]

if numAnomalies > 0
    stem(anomalyFreq,anomalyMag,'r','filled'); %[output:70fecfc1]
end

title('Test Engine - Candidate Acoustic Anomalies'); %[output:70fecfc1]
xlabel('Frequency (Hz)'); %[output:70fecfc1]
ylabel('Magnitude'); %[output:70fecfc1]
xlim([minAnalysisFreq Fs/2]); %[output:70fecfc1]
grid on; %[output:70fecfc1]
legend('Test Spectrum','Candidate Anomalies'); %[output:70fecfc1]
hold off; %[output:70fecfc1]

%%\ 12. RPM-RELATED SOUND ANALYSIS

% Estimate RPM by assuming the dominant frequency corresponds
% to a selected engine order.
%
% This is an estimate only. A dominant acoustic frequency may
% be a harmonic, resonance or accessory noise rather than a
% true engine-order component.

if selectedOrder <= 0
    error('Selected engine order must be positive.');
end

estimatedRPMNormal = ...
    60*dominantNormal/selectedOrder;

estimatedRPMTest = ...
    60*dominantTest/selectedOrder;

rpmDifference = abs(estimatedRPMNormal-estimatedRPMTest);

%%\ 13. CREST FACTOR ANALYSIS

% Crest factor = peak absolute amplitude / RMS amplitude.
% Higher values can indicate impulsive sounds, including
% knocks or clicks, but are not specific to engine faults.

crestNormal = max(abs(normalSig))/(rmsNormal+eps);
crestTest   = max(abs(testSig))/(rmsTest+eps);

%%\ 14. DISPLAY ALL RESULTS

fprintf('\n========================================\n'); %[output:855bfec7]
fprintf(' AUTOMOTIVE ENGINE ACOUSTIC ANALYSIS\n'); %[output:38c6a8d3]
fprintf('========================================\n'); %[output:4639a5c6]

fprintf('\n--- NORMAL ENGINE ---\n'); %[output:1eb35f79]

fprintf('Dominant Frequency        : %.2f Hz\n',dominantNormal); %[output:1bd2f380]
fprintf('Peak Magnitude            : %.6f\n',peak1); %[output:24b53151]
fprintf('RMS Amplitude             : %.6f\n',rmsNormal); %[output:30218e18]
fprintf('Spectral Centroid         : %.2f Hz\n',centroidNormal); %[output:2dbe9e49]
fprintf('Spectral Energy Proxy     : %.6f\n',energyNormal); %[output:8aa06829]

fprintf('Relative Acoustic Level   : %.2f dBFS\n',levelNormal_dB); %[output:63af8754]
fprintf('Level with Calibration    : %.2f dB\n',SPLNormal_dB); %[output:14d9fc85]

fprintf('Harmonic Content          : %.2f %%\n',harmonicPercentNormal); %[output:930e7f6e]
fprintf('Harmonic/Nonharmonic Ratio: %.2f dB\n',harmonicRatioNormal_dB); %[output:68b2ac23]

fprintf('Engine Order              : %.2f\n',engineOrderNormal); %[output:74ccf71b]
fprintf('Estimated RPM             : %.2f RPM\n',estimatedRPMNormal); %[output:3926f8ff]

fprintf('Background Noise Floor    : %.2f dBFS\n',noiseFloorNormal_dB); %[output:974a67ed]
fprintf('Crest Factor              : %.4f\n',crestNormal); %[output:1e1937e0]

fprintf('\n--- TEST ENGINE ---\n'); %[output:86d86241]

fprintf('Dominant Frequency        : %.2f Hz\n',dominantTest); %[output:82c90cd1]
fprintf('Peak Magnitude            : %.6f\n',peak2); %[output:65ecf658]
fprintf('RMS Amplitude             : %.6f\n',rmsTest); %[output:9e0f28b7]
fprintf('Spectral Centroid         : %.2f Hz\n',centroidTest); %[output:2a61af2c]
fprintf('Spectral Energy Proxy     : %.6f\n',energyTest); %[output:50e5d891]

fprintf('Relative Acoustic Level   : %.2f dBFS\n',levelTest_dB); %[output:10d40419]
fprintf('Level with Calibration    : %.2f dB\n',SPLTest_dB); %[output:0bbb3664]

fprintf('Harmonic Content          : %.2f %%\n',harmonicPercentTest); %[output:4d895959]
fprintf('Harmonic/Nonharmonic Ratio: %.2f dB\n',harmonicRatioTest_dB); %[output:94769d62]

fprintf('Engine Order              : %.2f\n',engineOrderTest); %[output:77cb2f44]
fprintf('Estimated RPM             : %.2f RPM\n',estimatedRPMTest); %[output:95cc7cd4]

fprintf('Background Noise Floor    : %.2f dBFS\n',noiseFloorTest_dB); %[output:73b7887c]
fprintf('Crest Factor              : %.4f\n',crestTest); %[output:6f3e7012]

%%\ 15. FEATURE COMPARISON

fprintf('\n--- FEATURE DIFFERENCES ---\n'); %[output:22a6f7fe]

fprintf('Dominant Frequency Difference : %.2f Hz\n', ... %[output:group:47970938] %[output:6786e4e1]
    abs(dominantNormal-dominantTest)); %[output:group:47970938] %[output:6786e4e1]

fprintf('RMS Difference                : %.6f\n', ... %[output:group:2a74182f] %[output:6d448863]
    abs(rmsNormal-rmsTest)); %[output:group:2a74182f] %[output:6d448863]

fprintf('Spectral Centroid Difference  : %.2f Hz\n', ... %[output:group:9d11d9e2] %[output:7a19d1a3]
    abs(centroidNormal-centroidTest)); %[output:group:9d11d9e2] %[output:7a19d1a3]

fprintf('Spectral Energy Difference    : %.6f\n', ... %[output:group:154683cd] %[output:2fc28ffe]
    abs(energyNormal-energyTest)); %[output:group:154683cd] %[output:2fc28ffe]

fprintf('Acoustic Level Difference     : %.2f dB\n', ... %[output:group:45e7b31d] %[output:29583c69]
    abs(levelNormal_dB-levelTest_dB)); %[output:group:45e7b31d] %[output:29583c69]

fprintf('Harmonic Content Difference   : %.2f percentage points\n', ... %[output:group:081b3ea1] %[output:2aa6b523]
    abs(harmonicPercentNormal-harmonicPercentTest)); %[output:group:081b3ea1] %[output:2aa6b523]

fprintf('Engine Order Difference       : %.2f\n', ... %[output:group:33fa9d25] %[output:67f127c2]
    abs(engineOrderNormal-engineOrderTest)); %[output:group:33fa9d25] %[output:67f127c2]

fprintf('Noise Floor Difference        : %.2f dB\n', ... %[output:group:84f9f4f6] %[output:732db0d6]
    abs(noiseFloorNormal_dB-noiseFloorTest_dB)); %[output:group:84f9f4f6] %[output:732db0d6]

fprintf('Crest Factor Difference       : %.4f\n', ... %[output:group:03e09481] %[output:57304c7d]
    abs(crestNormal-crestTest)); %[output:group:03e09481] %[output:57304c7d]

fprintf('Estimated RPM Difference      : %.2f RPM\n',rpmDifference); %[output:83758787]

%%\ 16. DISPLAY ACOUSTIC ANOMALIES

fprintf('\n--- CANDIDATE ACOUSTIC ANOMALIES ---\n'); %[output:0a47fcad]

if numAnomalies == 0 %[output:group:609f04da]
    fprintf('No peaks met the selected anomaly criteria.\n');
else
    for k = 1:numAnomalies
        fprintf('Anomaly %d: %.2f Hz, Magnitude = %.6f\n', ... %[output:04fb09f6]
            k,anomalyFreq(k),anomalyMag(k)); %[output:04fb09f6]
    end
end %[output:group:609f04da]

%%\ 17. HARMONIC TABLE

fprintf('\n--- HARMONIC ANALYSIS ---\n'); %[output:883b016e]
fprintf('Harmonic\tNormal (Hz)\tTest (Hz)\n'); %[output:04fb7625]

for k = 1:maxHarmonics %[output:group:08e9a7b8]
    fprintf('%d\t\t%.2f\t\t%.2f\n', ... %[output:60b8d27b]
        k,k*dominantNormal,k*dominantTest); %[output:60b8d27b]
end %[output:group:08e9a7b8]

fprintf('\n========================================\n'); %[output:0d3fb60e]
fprintf('Analysis completed successfully.\n'); %[output:3dd24a39]
fprintf('Compare features under similar recording conditions.\n'); %[output:7469d05b]
fprintf('Results are screening indicators, not a final diagnosis.\n'); %[output:39d86486]
fprintf('========================================\n'); %[output:3a6b7034]





